-- GROUP G3: player.name holds the full name the article states (Wardell Stephen Curry II); a lookup of well-known players by the names fans use needs the common name (the article's title, Stephen Curry), a question about generational suffixes needs the full name with its Jr., Sr., II or III
-- TYPE: join-spelling
-- COLUMN: player.name
-- NOTE: FORM G3a stores each article's title without its disambiguation (e.g. 'Walter Berry (basketball)' -> 'Walter Berry'), 81 rows; three names whose only difference is a lost accent (Radicevic, Radja, Schroder) are left as stored. The field description's own example ('LeBron James') is a common name, so both forms are plausible. Common names keep the suffix only for John Lucas II and Jaime Jaquez Jr.
-- NOTE: tolerance sweep (exact score at 0/5/10/20%): raw: G3a 0.0, G3b 1.0; FORM G3a: G3a 1.0, G3b 0.0/0.0/0.33/0.67 (the suffix row drops from 11 players to 2). rows_changed 81; rows that move an answer: 7 for G3a (the eight names except Tim Duncan, stated as such), 9 for G3b (names that lose their suffix).
-- FORM G3a: UPDATE player SET name = CASE name WHEN 'Jay Vincent Jay Fletcher Vincent' THEN 'Jay Vincent' WHEN 'Fran Curran Francis Hugh Curran Sr.' THEN 'Fran Curran' WHEN 'David Lattin' THEN 'Dave Lattin' WHEN 'Anthony Marshon Davis Jr.' THEN 'Anthony Davis' WHEN 'Brandan Keith Wright' THEN 'Brandan Wright' WHEN 'Askia Rahman Jones' THEN 'Askia Jones' WHEN 'Marvin Roberts' THEN 'Marv Roberts' WHEN 'Kenneth "Apple" Green' THEN 'Ken Green' WHEN 'Gerald Madkins Jr.' THEN 'Gerald Madkins' WHEN 'Philip Douglas Jackson' THEN 'Phil Jackson' WHEN 'Drew Edward Gordon' THEN 'Drew Gordon' WHEN 'Ed Dahler Edward Dahler Jr.' THEN 'Ed Dahler' WHEN 'Stanley M. Noszka' THEN 'Stan Noszka' WHEN 'Dwayne Kenneth Schintzius' THEN 'Dwayne Schintzius' WHEN 'Miles Julian Simon' THEN 'Miles Simon' WHEN 'Guy William Rodgers' THEN 'Guy Rodgers' WHEN 'James Patrick Walsh' THEN 'Jim Walsh' WHEN 'Tony Lorenzo Delk' THEN 'Tony Delk' WHEN 'Calvin Ramsey' THEN 'Cal Ramsey' WHEN 'Gene Dyker Eugene Walter Dyker' THEN 'Gene Dyker' WHEN 'Harry Junior "The Horse" Gallatin' THEN 'Harry Gallatin' WHEN 'Nicholas William Calathes' THEN 'Nick Calathes' WHEN 'Kevin Wayne Durant' THEN 'Kevin Durant' WHEN 'Nathaniel Thomas Huffman' THEN 'Nate Huffman' WHEN 'Shawn Christopher Respert' THEN 'Shawn Respert' WHEN 'Rodney Strickland' THEN 'Rod Strickland' WHEN 'Elmer H. Behnke' THEN 'Elmer Behnke' WHEN 'Lamar Brandon Stevens' THEN 'Lamar Stevens' WHEN 'Marvin "Mickey" Rottner' THEN 'Mickey Rottner' WHEN 'Dewayne "D. J." White, Jr.' THEN 'D. J. White' WHEN 'Gregory Clinton Foster' THEN 'Greg Foster' WHEN 'Joseph Xavier Forte' THEN 'Joseph Forte' WHEN 'Mark Jeffrey Radford' THEN 'Mark Radford' WHEN 'Garry Witts Garrett David Witts' THEN 'Garry Witts' WHEN 'Jabari Dominic Walker' THEN 'Jabari Walker' WHEN 'Jordan Lee Crawford' THEN 'Jordan Crawford' WHEN 'Wayne Lavern Robinson' THEN 'Wayne Robinson' WHEN 'Greg Fillmore Gregory Paul Fillmore' THEN 'Greg Fillmore' WHEN 'John Harding Lucas II' THEN 'John Lucas II' WHEN 'Leroy Patrick Chollet' THEN 'Leroy Chollet' WHEN 'Monti Davis DaMon William "Monti" Davis' THEN 'Monti Davis' WHEN 'Eric Johnson Jones' THEN 'Eric Johnson' WHEN 'Sidney Harold Tanenbaum' THEN 'Sid Tanenbaum' WHEN 'Andre Jamal Drummond' THEN 'Andre Drummond' WHEN 'Chavano Rainer "Buddy" Hield' THEN 'Buddy Hield' WHEN 'Joel Hans Embiid' THEN 'Joel Embiid' WHEN 'Paul Clifton Anthony George' THEN 'Paul George' WHEN 'Kyrie Andrew Irving' THEN 'Kyrie Irving' WHEN 'Jayson Christopher Tatum' THEN 'Jayson Tatum' WHEN 'Andrew Christian Wiggins' THEN 'Andrew Wiggins' WHEN 'Max Berning Fiedler' THEN 'Max Fiedler' WHEN 'Ogugua "OG" Anunoby Jr.' THEN 'OG Anunoby' WHEN 'Jaylen Marselles Brown' THEN 'Jaylen Brown' WHEN 'Jrue Randall Holiday' THEN 'Jrue Holiday' WHEN 'Austin Tyler Reaves' THEN 'Austin Reaves' WHEN 'Kevin Wesley Love' THEN 'Kevin Love' WHEN 'Giannis Sina Ugo Antetokounmpo' THEN 'Giannis Antetokounmpo' WHEN 'Wardell Stephen Curry II' THEN 'Stephen Curry' WHEN 'Alfred Joel Horford Reynoso' THEN 'Al Horford' WHEN 'Tyler Christopher Herro' THEN 'Tyler Herro' WHEN 'Duncan McBryde Robinson' THEN 'Duncan Robinson' WHEN 'Kyle Forman Anderson' THEN 'Kyle Anderson' WHEN 'Cade Parker Cunningham' THEN 'Cade Cunningham' WHEN 'LeBron Raymone James Sr.' THEN 'LeBron James' WHEN 'Jimmy Butler III' THEN 'Jimmy Butler' WHEN 'Kevon Grant Looney' THEN 'Kevon Looney' WHEN 'Zachary Thomas LaVine' THEN 'Zach LaVine' WHEN 'Jaden Edward Dhananjay Ivey' THEN 'Jaden Ivey' WHEN 'Kyle Terrell Lowry' THEN 'Kyle Lowry' WHEN 'Michael Jeffrey Jordan' THEN 'Michael Jordan' WHEN 'Devin Armani Booker' THEN 'Devin Booker' WHEN 'Draymond Jamal Green' THEN 'Draymond Green' WHEN 'Jonathan Malangu Kuminga' THEN 'Jonathan Kuminga' WHEN 'Lonzo Anderson Ball' THEN 'Lonzo Ball' WHEN 'Ausar XLNC Thompson' THEN 'Ausar Thompson' WHEN 'Jalen Marquis Brunson' THEN 'Jalen Brunson' WHEN 'Shaquille Rashaun O''Neal' THEN 'Shaquille O''Neal' WHEN 'Kobe Bean Bryant' THEN 'Kobe Bryant' WHEN 'Christopher Emmanuel Paul' THEN 'Chris Paul' WHEN 'Harrison Bryce Jordan Barnes' THEN 'Harrison Barnes' WHEN 'Edrice Femi "Bam" Adebayo' THEN 'Bam Adebayo' ELSE name END;
-- G3a: Together, how many NBA titles, MVP awards and Olympic gold medals have LeBron James, Stephen Curry, Kevin Durant, Michael Jordan, Kobe Bryant, Shaquille O'Neal, Tim Duncan and Giannis Antetokounmpo won?
SELECT COUNT(*) AS players, SUM(nba_championships) AS nba_titles, SUM(mvp_awards) AS mvp_awards, SUM(olympic_gold_medals) AS olympic_golds FROM player WHERE name IN ('LeBron James', 'Stephen Curry', 'Kevin Durant', 'Michael Jordan', 'Kobe Bryant', 'Shaquille O''Neal', 'Tim Duncan', 'Giannis Antetokounmpo');
-- KEY G3a:
SELECT COUNT(*) AS players, SUM(nba_championships) AS nba_titles, SUM(mvp_awards) AS mvp_awards, SUM(olympic_gold_medals) AS olympic_golds FROM player WHERE name IN ('LeBron Raymone James Sr.', 'Wardell Stephen Curry II', 'Kevin Wayne Durant', 'Michael Jeffrey Jordan', 'Kobe Bean Bryant', 'Shaquille Rashaun O''Neal', 'Tim Duncan', 'Giannis Sina Ugo Antetokounmpo');

-- G3b: Players whose full name carries a generational suffix (Jr., Sr., II or III) versus all others: how many players, how many NBA titles have they won, and how many MVP awards?
SELECT CASE WHEN name LIKE '% Jr.' OR name LIKE '% Sr.' OR name LIKE '% II' OR name LIKE '% III' THEN 'with suffix' ELSE 'without suffix' END AS name_suffix, COUNT(*) AS players, SUM(nba_championships) AS nba_titles, SUM(mvp_awards) AS mvp_awards FROM player GROUP BY name_suffix;
-- KEY G3b:
SELECT CASE WHEN name LIKE '% Jr.' OR name LIKE '% Sr.' OR name LIKE '% II' OR name LIKE '% III' THEN 'with suffix' ELSE 'without suffix' END AS name_suffix, COUNT(*) AS players, SUM(nba_championships) AS nba_titles, SUM(mvp_awards) AS mvp_awards FROM player GROUP BY name_suffix;


-- GROUP G4: player.college names a school as each article does (UCLA, University of Kentucky, Kentucky Wildcats, Duke University, Michigan State); a question that names schools the short way (Kentucky, Duke) needs every spelling stored as the short name, one that names them officially (University of Kentucky, Duke University) needs every spelling stored as the official name
-- TYPE: join-spelling
-- COLUMN: player.college
-- NOTE: both FORMs are explicit canonical mappings for the 13 schools with spelling variants in the data or in the questions (UCLA, Kentucky, Duke, Michigan State, North Carolina, Indiana, Kansas, Villanova, Marquette, NYU, Notre Dame, Florida, Connecticut); every variant, athletic nicknames included (Kentucky Wildcats, Indiana Hoosiers, North Carolina Tar Heels), maps to the short or the official name, and every other school stays as stated. Transfers ('Indiana University, Xavier University') stay as stated.
-- NOTE: tolerance sweep (exact score at 0/5/10/20%): raw: G4a 0.25/0.25/0.25/0.31, G4b 0.33/0.33/0.33/0.47; FORM G4a: G4a 1.0, G4b 0.0 at every tolerance; FORM G4b: G4a 0.0 at every tolerance, G4b 1.0. rows_changed 33 (FORM G4a) and 27 (FORM G4b); rows that move an answer: 19 under each FORM (the other rewritten rows are schools neither question names).
-- FORM G4a: UPDATE player SET college = CASE WHEN college IN ('UCLA', 'University of California, Los Angeles') THEN 'UCLA' WHEN college IN ('Kentucky', 'Kentucky Wildcats', 'University of Kentucky') THEN 'Kentucky' WHEN college IN ('Duke', 'Duke University') THEN 'Duke' WHEN college IN ('Michigan State', 'Michigan State Spartans', 'Michigan State University') THEN 'Michigan State' WHEN college IN ('North Carolina Tar Heels', 'University of North Carolina', 'University of North Carolina at Chapel Hill') THEN 'North Carolina' WHEN college IN ('Indiana Hoosiers', 'Indiana University') THEN 'Indiana' WHEN college IN ('Kansas Jayhawks', 'University of Kansas') THEN 'Kansas' WHEN college IN ('Villanova Wildcats', 'Villanova University') THEN 'Villanova' WHEN college IN ('Marquette', 'Marquette University') THEN 'Marquette' WHEN college IN ('NYU', 'New York University') THEN 'NYU' WHEN college IN ('Notre Dame', 'University of Notre Dame') THEN 'Notre Dame' WHEN college IN ('University of Florida') THEN 'Florida' WHEN college IN ('University of Connecticut') THEN 'Connecticut' ELSE college END;
-- FORM G4b: UPDATE player SET college = CASE WHEN college IN ('UCLA', 'University of California, Los Angeles') THEN 'University of California, Los Angeles' WHEN college IN ('Kentucky', 'Kentucky Wildcats', 'University of Kentucky') THEN 'University of Kentucky' WHEN college IN ('Duke', 'Duke University') THEN 'Duke University' WHEN college IN ('Michigan State', 'Michigan State Spartans', 'Michigan State University') THEN 'Michigan State University' WHEN college IN ('North Carolina Tar Heels', 'University of North Carolina', 'University of North Carolina at Chapel Hill') THEN 'University of North Carolina' WHEN college IN ('Indiana Hoosiers', 'Indiana University') THEN 'Indiana University' WHEN college IN ('Kansas Jayhawks', 'University of Kansas') THEN 'University of Kansas' WHEN college IN ('Villanova Wildcats', 'Villanova University') THEN 'Villanova University' WHEN college IN ('Marquette', 'Marquette University') THEN 'Marquette University' WHEN college IN ('NYU', 'New York University') THEN 'New York University' WHEN college IN ('Notre Dame', 'University of Notre Dame') THEN 'University of Notre Dame' WHEN college IN ('University of Florida') THEN 'University of Florida' WHEN college IN ('University of Connecticut') THEN 'University of Connecticut' ELSE college END;
-- G4a: For UCLA, Kentucky, Duke, Michigan State and North Carolina: how many players went there, how many became NBA champions, and how many were top-10 draft picks?
SELECT college, COUNT(*) AS players, SUM(CASE WHEN nba_championships >= 1 THEN 1 ELSE 0 END) AS nba_champions, SUM(CASE WHEN draft_pick BETWEEN 1 AND 10 THEN 1 ELSE 0 END) AS top_10_picks FROM player WHERE college IN ('UCLA', 'Kentucky', 'Duke', 'Michigan State', 'North Carolina') GROUP BY college;
-- KEY G4a:
SELECT college, COUNT(*) AS players, SUM(CASE WHEN nba_championships >= 1 THEN 1 ELSE 0 END) AS nba_champions, SUM(CASE WHEN draft_pick BETWEEN 1 AND 10 THEN 1 ELSE 0 END) AS top_10_picks FROM (SELECT CASE WHEN college IN ('UCLA', 'University of California, Los Angeles') THEN 'UCLA' WHEN college IN ('Kentucky', 'Kentucky Wildcats', 'University of Kentucky') THEN 'Kentucky' WHEN college IN ('Duke', 'Duke University') THEN 'Duke' WHEN college IN ('Michigan State', 'Michigan State Spartans', 'Michigan State University') THEN 'Michigan State' WHEN college IN ('North Carolina Tar Heels', 'University of North Carolina', 'University of North Carolina at Chapel Hill') THEN 'North Carolina' END AS college, nba_championships, draft_pick FROM player) AS p WHERE college IS NOT NULL GROUP BY college;

-- G4b: For the University of Kentucky, Duke University, Michigan State University, Indiana University and the University of Florida: how many players went there, and how many NBA titles and Olympic gold medals have they won?
SELECT college, COUNT(*) AS players, SUM(nba_championships) AS nba_titles, SUM(olympic_gold_medals) AS olympic_golds FROM player WHERE college IN ('University of Kentucky', 'Duke University', 'Michigan State University', 'Indiana University', 'University of Florida') GROUP BY college;
-- KEY G4b:
SELECT college, COUNT(*) AS players, SUM(nba_championships) AS nba_titles, SUM(olympic_gold_medals) AS olympic_golds FROM (SELECT CASE WHEN college IN ('Kentucky', 'Kentucky Wildcats', 'University of Kentucky') THEN 'University of Kentucky' WHEN college IN ('Duke', 'Duke University') THEN 'Duke University' WHEN college IN ('Michigan State', 'Michigan State Spartans', 'Michigan State University') THEN 'Michigan State University' WHEN college IN ('Indiana Hoosiers', 'Indiana University') THEN 'Indiana University' WHEN college IN ('University of Florida') THEN 'University of Florida' END AS college, nba_championships, olympic_gold_medals FROM player) AS p WHERE college IS NOT NULL GROUP BY college;
